"use client";

import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";

interface NewProductInput {
  title: string;
  price: number;
  category: string;
}

async function addProduct(newProduct: NewProductInput) {
  const res = await fetch("https://dummyjson.com/products/add", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(newProduct),
  });

  if (!res.ok) { throw new Error("Nie udało się dodać produktu");}
  return res.json();
}

export default function AddProductForm() {
  const queryClient = useQueryClient();
  const [title, setTitle] = useState("");
  const [price, setPrice] = useState("");
  const [category, setCategory] = useState("");

  const mutation = useMutation({
    mutationFn: addProduct,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["products"] });
      setTitle("");
      setPrice("");
      setCategory("");
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !price || !category) return;

    mutation.mutate({title, price: Number(price), category,});
  };

  return (
    <form onSubmit={handleSubmit} className="border p-4 rounded-lg bg-card mb-8 space-y-4 shadow-sm">
      <h2 className="text-xl font-semibold">Dodaj nowy produkt</h2>
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <input type="text"  placeholder="Tytuł produktu" value={title}
          onChange={(e) => setTitle(e.target.value)}
          className="border rounded px-3 py-2 text-sm bg-background" required/>
        <input type="number" placeholder="Cena" value={price}
          onChange={(e) => setPrice(e.target.value)}
          className="border rounded px-3 py-2 text-sm bg-background"
          required min="0" step="0.01"/>
        <input type="text" placeholder="Kategoria" value={category}
          onChange={(e) => setCategory(e.target.value)}
          className="border rounded px-3 py-2 text-sm bg-background" required />
      </div>

      <button type="submit" disabled={mutation.isPending} className="px-4 py-2 bg-blue-600 text-white rounded text-sm hover:bg-blue-700 disabled:opacity-50 transition-colors" >
        {mutation.isPending ? "Dodawanie..." : "Dodaj produkt"}
      </button>

      {mutation.isSuccess && (
        <p className="text-sm text-green-600">Produkt został pomyślnie wysłany!</p>
      )}
      {mutation.isError && (
        <p className="text-sm text-red-600">Błąd: {(mutation.error as Error).message}</p>
      )}
    </form>
  );
}