"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Product, ProductsResponse } from "@/src/types/Product";
import AddProductForm from "./AddProductForm";

interface ProductsListProps {
  initialData: ProductsResponse;
}

async function fetchProducts(search: string): Promise<ProductsResponse> {
  const url = search.trim()
    ? `https://dummyjson.com/products/search?q=${encodeURIComponent(search.trim())}`
    : "https://dummyjson.com/products";

  const res = await fetch(url);
  if (!res.ok) throw new Error("Błąd podczas pobierania produktów");
  return res.json();
}

export default function ProductsList({ initialData }: ProductsListProps) {
  const [search, setSearch] = useState("");

  const { data, isLoading, isFetching, error } = useQuery({
    queryKey: ["products", search],
    queryFn: () => fetchProducts(search),
    initialData: search === "" ? initialData : undefined,
    staleTime: 60_000
  });

  return (
    <div>
      <AddProductForm />

      <div className="mb-6 flex items-center gap-3">
        <input type="text" placeholder="Szukaj produktów..." value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="border rounded px-4 py-2 w-full max-w-md bg-background text-sm"/>
        {isFetching && <span className="text-xs text-muted-foreground animate-pulse">Aktualizacja...</span>}
      </div>

      {isLoading && <div>Ładowanie produktów...</div>}
      {error && <div className="text-red-500">Wystąpił błąd: {(error as Error).message}</div>}

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
        {data?.products.map((product: Product) => (
          <div key={product.id} className="border rounded-lg p-4 shadow-xs flex flex-col justify-between bg-card">
            <div>
              {product.thumbnail && (
                <img src={product.thumbnail} alt={product.title}
                  className="w-full h-48 object-cover rounded-md mb-3"/>
              )}
              <h3 className="font-semibold text-lg">{product.title}</h3>
              <p className="text-sm text-muted-foreground capitalize">{product.category}</p>
            </div>
            <p className="text-lg font-bold mt-3">${product.price}</p>
          </div>
        ))}
      </div>

      {data?.products.length === 0 && !isLoading && (
        <p className="text-muted-foreground mt-4">Nie znaleziono żadnych produktów.</p>
      )}
    </div>
  );
}